source('R/build_mcp_action_states.R')
checks<-0L
check<-function(x,msg){checks<<-checks+1L;if(!isTRUE(x))stop(msg,call.=FALSE)}
fails<-function(x)inherits(tryCatch({force(x);NULL},error=identity),'error')
allowed<-c('R/build_mcp_action_states.R','R/test_mcp_action_states.R','docs/mcp-action-state-audit.md','PROJECT_CONTEXT.md','docs/status.md','docs/data-source-contract.md')
oldfiles<-unique(c(system2('git','ls-files',stdout=TRUE),list.files('data/raw',recursive=TRUE,full.names=TRUE),list.files('data/pilot',recursive=TRUE,full.names=TRUE)))
oldfiles<-setdiff(oldfiles,allowed);oldfiles<-oldfiles[!grepl('/mcp-action-states-v1-',oldfiles)]
oldpins<-vapply(oldfiles,mcp_sha,'')
fixture<-function(first,second='',server=1L){a<-action_point(first,second,server)$actions;a$action_index<-seq_len(nrow(a));a$action_id<-paste('FIXTURE',a$action_index,sep='|');a}
# Independently stated expected boundaries and incoming observations.
a<-fixture('4n','4b27f1n@');x<-state_point(a,1L)
check(identical(x$pre_next_domain,c('Serve','Serve','Return','Rally')),'Fault, second serve, return, +1 boundaries')
check(identical(x$pre_serve_number,c(1L,2L,2L,2L)),'Second serve known only after first fault')
check(identical(x$pre_in_play_strokes,c(0L,0L,1L,2L)),'Fault excluded from in-play ordinal')
check(x$pre_incoming_shot_type[4]=='backhand_groundstroke'&&x$pre_incoming_direction[4]=='2'&&x$pre_incoming_return_depth[4]=='7','Only preceding return describes incoming +1 context')
check(x$post_terminal_status[4]=='UNFORCED_ERROR'&&x$post_terminal_winner_role[4]=='RECEIVER','Attempted +1 error belongs to server, receiver wins')
check(x$incoming_source_action_id[4]==a$action_id[3]&&x$serve_number_source_action_id[4]==a$action_id[1],'Field-specific prior provenance')
for(raw in c('6*','6f37*','4b27f1*','6b29C','4b27f1b2C')) {
 a<-fixture(raw);x<-state_point(a,1L);y<-state_point(fixture(raw,server=2L),2L)
 check(identical(x[,state_pre_fields],y[,state_pre_fields]),paste('Global source-player relabeling',raw))
 check(identical(x$post_actor_role,y$post_actor_role)&&identical(x$post_terminal_winner_role,y$post_terminal_winner_role),paste('Perspective independent of numeric player',raw))
 check(all(x$local_boundary_supported)&&tail(x$post_boundary,1)=='TERMINAL',paste('Supported terminal absorption',raw))
}
a<-fixture('cc4n','c4b27f1*');x<-state_point(a,1L)
check(all(x$pre_serve_number==c(1L,1L,1L,2L,2L,2L,2L)),'Lets replay same first/second serve')
check(identical(x$pre_in_play_strokes,c(0L,0L,0L,0L,0L,1L,2L)),'Lets do not increment stroke count')
a<-fixture('V','4b27f1*');x<-state_point(a,1L)
check(x$post_kind[1]=='FIRST_SERVE_FORFEIT'&&x$pre_serve_number[2]==2&&x$pre_in_play_strokes[2]==0,'Forfeit is administrative, not a tennis attempt')
a<-fixture('4n','5d');x<-state_point(a,1L)
check(tail(x$post_terminal_winner_role,1)=='RECEIVER'&&tail(x$post_boundary,1)=='TERMINAL','Double fault ends point')
a<-fixture('6b29C');x<-state_point(a,1L)
check(tail(x$post_kind,1)=='INCORRECT_CHALLENGE'&&nrow(x)==3&&x$pre_in_play_strokes[3]==2&&tail(x$post_terminal_winner_role,1)=='RECEIVER','Challenge creates no third stroke')
a<-fixture('6*');extra<-fixture('4f1*')[2,,drop=FALSE];extra$action_index<-2L;extra$action_id<-'AFTER_TERMINAL';x<-state_point(rbind(a,extra),1L)
check(x$pre_boundary[2]=='TERMINAL'&&!x$local_boundary_supported[2]&&x$local_boundary_reason[2]=='ACTION_AFTER_TERMINAL','No transitions out of terminal')
check(x$post_boundary[2]=='TERMINAL','Terminal state remains absorbing even on inconsistent suffix')
# Current outcomes and later strokes cannot leak backward; incoming observations can.
x<-state_point(fixture('4b27f1*'),1L);y<-state_point(fixture('4b27f1n@'),1L)
check(identical(x[,state_pre_fields],y[,state_pre_fields]),'Current terminal/error does not enter any earlier pre predictor')
check(tail(x$post_terminal_winner_role,1)!=tail(y$post_terminal_winner_role,1),'Terminal perturbation positive control')
y<-state_point(fixture('4f37f1*'),1L)
check(identical(x[1:2,state_pre_fields],y[1:2,state_pre_fields]),'Current return properties excluded from its own pre state')
check(!identical(x[3,state_pre_fields],y[3,state_pre_fields]),'Observed earlier return affects later +1 state positive control')
y<-state_point(fixture('4b27f1Z'),1L)
check(identical(x[1:3,state_pre_fields],y[1:3,state_pre_fields]),'Later unsupported suffix cannot alter earlier pre states')
a<-fixture('4b27f1*');a$serve_number[3]<-1L;a$direction[3]<-'3';a$shot_type[3]<-'backhand_groundstroke';a$terminal[3]<-'FORCED_ERROR';y<-state_point(a,1L)
check(identical(x[,state_pre_fields],y[,state_pre_fields]),'Current action property mutation excluded from pre fields')
for(raw in c('S','R','4b1Z','')){x<-state_point(fixture(raw),1L);check(any(!x$local_boundary_supported),paste('Missing/unsupported observation explicit',raw))}
x<-state_point(fixture('0b00q0n@'),1L)
check(x$pre_incoming_direction_status[3]=='SOURCE_UNKNOWN'&&x$pre_incoming_depth_status[3]=='SOURCE_UNKNOWN','Unknown direction/depth preserved, not zero')
check(!any(grepl('terminal|winner|raw|quality|position|attack|defen',state_pre_fields,ignore.case=TRUE)),'Predictor allowlist excludes outcomes, raw future notation and inferred quality')
cat('State fixtures passed; auditing frozen ledgers.\n')
input<-state_load();r<-build_mcp_action_states(input);s<-r[['action-states']];plus<-r[['serve-plus1']];cov<-r[['coverage-summary']];prov<-r[['field-provenance']]
check(nrow(s)==38593&&!anyDuplicated(s$action_id)&&nrow(plus)==7333&&!anyDuplicated(plus$point_id),'Exact unique action/point accounting')
check(length(unique(s$match_id))==44&&sum(plus$tour_file=='ATP')==4092&&sum(plus$tour_file=='WTA')==3241,'Frozen match/tour coverage')
check(all(!s$transition_usable[!s$point_validated])&&sum(!plus$point_parse_status%in%c('PARSED','PARSED_WITH_EXPLICIT_UNKNOWNS'))==1096,'No unresolved point gains full validation through prefix')
check(all(s$point_exclusion_reasons[s$authority_conflict]!='')&&!any(s$transition_usable[s$authority_conflict]),'Authority conflicts withheld')
check(all(s$owner_domain%in%c('Serve','Return','Rally','ADMIN','UNRESOLVED'))&&all(s$owner_role[s$owner_domain%in%c('Serve','Return','Rally')]%in%c('SERVER','RECEIVER')),'Unique tennis ownership and player perspective')
check(all(s$pre_next_actor_role[s$transition_usable&s$owner_domain=='Serve']=='SERVER')&&all(s$post_actor_role[s$transition_usable&s$owner_domain=='Return']=='RECEIVER'),'Serve/return perspective')
check(all(s$post_boundary[s$transition_usable&s$post_terminal_status!='']=='TERMINAL'),'All usable terminal boundaries absorb')
terminal<-s[s$transition_usable&s$post_boundary=='TERMINAL',];j<-match(terminal$point_id,paste(input$points$match_id,input$points$Pt,sep='|'))
check(nrow(terminal)==6237&&!anyDuplicated(terminal$point_id)&&all(terminal$post_terminal_winner_role==ifelse(input$points$recorded_winner[j]==input$points$server[j],'SERVER','RECEIVER')),'One terminal and independently correct winner for every usable point')
check(all(s$post_kind[s$owner_domain=='ADMIN']%in%c('INCORRECT_CHALLENGE','FIRST_SERVE_FORFEIT'))&&!any(s$tennis_action_usable[s$owner_domain=='ADMIN']),'Admin creates no tennis-stroke credit')
check(sum(plus$validated_attempt)==3986&&sum(plus$attempted_error,na.rm=TRUE)==724&&sum(plus$disposition=='KNOWN_ABSENT')==2251&&sum(plus$disposition=='UNKNOWN_OPPORTUNITY')==113&&sum(plus$disposition=='UNVALIDATED_OBSERVED_PREFIX')==983,'Independent frozen +1 reconciliation')
check(all(is.na(plus$attempted_error[!plus$validated_attempt])),'Undefined conditional errors remain missing')
check(sum(table(plus$disposition))==7333,'Opportunity partition retains every point')
check(all(s$prior_action_id[s$action_index==1]=='')&&all(s$pre_serve_number[s$action_index==1]==1),'Initial states cannot read current first action')
for(id in unique(s$point_id)){z<-s[s$point_id==id,];check(identical(z$action_index,seq_len(nrow(z))),paste('Ordered transitions',id));past<-match(z$incoming_source_action_id,z$action_id);check(all(is.na(past)|past<z$action_index),paste('Incoming provenance strictly prior',id))}
check(setequal(prov$field[prov$information_class=='PRE_ACTION_PREDICTOR'],state_pre_fields),'Complete explicit predictor provenance allowlist')
for(k in names(r)[1:3])check(setequal(names(r[[k]]),prov$field[prov$output==k]),paste('Every exported field classified',k))
check(grepl('preceding observable state plus current action',prov$source[prov$field=='post_boundary'],fixed=TRUE),'Post-boundary provenance includes prior state')
check(prov$source[prov$field=='post_return_depth']=='actions.return_depth','Recorded return-depth provenance is explicit')
check(sum(cov$points[cov$level=='tour'])==7333&&sum(cov$points[cov$level=='match'])==7333,'Tour/match point summaries reconcile')
check(sum(cov$transitions[cov$level=='tour'])==38593&&sum(cov$usable_transitions[cov$level=='match'])==cov$usable_transitions[1],'Transition summaries reconcile')
check(all(cov$transition_retention>=0&cov$transition_retention<=1),'Usable fractions bounded')
bad<-input;bad$actions$action_id[2]<-bad$actions$action_id[1];check(fails(state_check_input(bad)),'Duplicate action fails closed')
bad<-input;bad$points<-bad$points[-1,];check(fails(state_check_input(bad)),'Missing frozen point fails closed')
bad<-input;bad$actions$server[1]<-3L;check(fails(state_check_input(bad)),'Invalid perspective fails closed')
# Alter audit-only outcome/Notes values: states and eligibility must not change.
perturbed<-input;perturbed$points$recorded_winner<-3L-perturbed$points$recorded_winner
perturbed$points$inferred_winner<-3L-perturbed$points$inferred_winner
perturbed$points$raw_notes<-'AUDIT_ONLY';perturbed$actions$raw_notes<-'AUDIT_ONLY'
z<-build_mcp_action_states(perturbed)
check(identical(s[,c('action_id',state_pre_fields,'transition_usable')],z[['action-states']][,c('action_id',state_pre_fields,'transition_usable')]),'All point outcomes and Notes excluded from predictor/eligibility construction')
check(!identical(cov$server_won_validated_points,z[['coverage-summary']]$server_won_validated_points),'Outcome-count diagnostic positive control')
cat('Frozen accounting passed; checking permutations, reruns and preservation.\n')
permuted<-input;permuted$actions<-permuted$actions[nrow(permuted$actions):1,];permuted$points<-permuted$points[nrow(permuted$points):1,];permuted$matches<-permuted$matches[nrow(permuted$matches):1,]
z<-build_mcp_action_states(permuted)
check(identical(r,z),'Action/point/match permutation invariance')
state_install(r);paths<-paste0(state_prefix,state_outputs,'.csv');pins<-vapply(paths,mcp_sha,'')
for(k in names(z)){f<-tempfile();mcp_write(z[[k]],f);check(mcp_sha(f)==pins[[paste0(state_prefix,k,'.csv')]],paste('Byte-identical rerun',k));unlink(f)}
state_install(z);check(identical(pins,vapply(paths,mcp_sha,'')),'Idempotent atomic-per-file installation')
bad<-r;bad[['action-states']]$raw_token[1]<-'REFUSE';check(fails(state_install(bad)),'Existing differing release refused');check(identical(pins,vapply(paths,mcp_sha,'')),'Rejected installation preserves every output')
check(setequal(system2('git',c('check-ignore','--',shQuote(paths)),stdout=TRUE),paths),'All four outputs ignored')
check(setequal(list.files('data/pilot',pattern='^mcp-action-states-v1-',full.names=TRUE),paths),'Exact four-output scope')
check(!length(list.files('data/pilot',pattern='^\\.mcp-states-',all.files=TRUE)),'No staging residue')
check(identical(oldpins,vapply(oldfiles,mcp_sha,'')),'Historical and pinned artifacts unchanged')
changed<-system2('git',c('diff','HEAD','--name-only'),stdout=TRUE);untracked<-system2('git',c('ls-files','--others','--exclude-standard'),stdout=TRUE)
check(all(c(changed,untracked)%in%allowed),'Exact intended tracked scope')
cat(sprintf('PASS: %d focused checks; %d historical files preserved; four byte-identical outputs.\n',checks,length(oldfiles)))
